package com.yeyamo_mobile.api.payment_service.infrastructure.persistence;
import java.util.*;import java.math.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.*;
public interface RefundRepository extends JpaRepository<RefundEntity,UUID>{Optional<RefundEntity>findByIdempotencyKey(String key);Optional<RefundEntity>findByProviderRefundId(String id);List<RefundEntity>findByPaymentIdOrderByCreatedAtDesc(UUID payment);@Query("select coalesce(sum(r.amount),0) from RefundEntity r where r.payment.id=:payment and r.status='SUCCEEDED'")BigDecimal succeededAmount(@Param("payment")UUID payment);@Query(value="SELECT p.id FROM payments p JOIN payment_refunds r ON r.payment_id=p.id AND r.status='SUCCEEDED' GROUP BY p.id,p.amount HAVING SUM(r.amount)>p.amount",nativeQuery=true)List<UUID>inconsistentRefundPayments();}
